import sys

def solve():
    s = sys.stdin.read().strip()
    counts = {'C': 0, 'H': 0, 'E': 0, 'F': 0}

    c_count = 0
    h_count = 0
    e_count = 0
    f_count = 0

    for char in s:
        if char == 'C':
            c_count += 1
        elif char == 'H':
            if c_count > 0:
                h_count += 1
                c_count -= 1
        elif char == 'E':
            if h_count > 0:
                e_count += 1
                h_count -= 1
        elif char == 'F':
            if e_count > 0:
                f_count += 1
                e_count -= 1

    print(f_count)

if __name__ == "__main__":
    solve()
